  "rules": {
    "R1": {
      "severity": "Chặn baseline",
      "rule": "Mọi Requirement có ít nhất một satisfiedBy"
    },
    "R2": {
      "severity": "Chặn baseline",
      "rule": "Mọi NFR có targetValue và targetUnit"
    },
    "R3": {
      "severity": "Chặn baseline",
      "rule": "Mọi FR có allocatedTo một Module"
    },
    "R4": {
      "severity": "Cảnh báo",
      "rule": "Mọi Decision có rationale; nếu có selects thì có rejects hoặc noAlternativeNote"
    },
    "R5": {
      "severity": "Chặn baseline",
      "rule": "Mọi Integration có withParty, securedBy, boundedBy; mọi Message có hasSchema"
    },
    "R6": {
      "severity": "Chặn baseline",
      "rule": "Mọi Integration outbound có hasTimeoutPolicy, hasRetryPolicy, usesPool"
    },
    "R7": {
      "severity": "Chặn baseline",
      "rule": "connectMs < readMs < totalMs và poolAcquireMs < readMs"
    },
    "R8": {
      "severity": "Chặn baseline",
      "rule": "totalMs < responseBudgetMs của mọi Scenario gọi tích hợp đó"
    },
    "R9": {
      "severity": "Chặn baseline",
      "rule": "Tích hợp ghi không idempotent: RetryPolicy.idempotentOnly=true hoặc có Header idempotency key"
