      "rule": "Mọi Requirement có ít nhất một satisfiedBy"
    },
    "R2": {
      "severity": "Chặn baseline",
      "rule": "Mọi NFR có targetValue và targetUnit"
    },
    "R3": {
      "severity": "Chặn baseline",
      "rule": "Mọi FR có allocatedTo một Module"
    },
    "R4": {
      "severity": "Cảnh báo",
      "rule": "Mọi Decision có rationale; nếu có selects thì có rejects hoặc noAlternativeNote"
    },
    "R5": {
      "severity": "Chặn baseline",
      "rule": "Mọi Integration có withParty, securedBy, boundedBy; mọi Message có hasSchema"
    },
    "R6": {
      "severity": "Chặn baseline",
      "rule": "Mọi Integration outbound có hasTimeoutPolicy, hasRetryPolicy, usesPool"
    },
    "R7": {
      "severity": "Chặn baseline",
      "rule": "connectMs < readMs < totalMs và poolAcquireMs < readMs"
    },
    "R8": {
      "severity": "Chặn baseline",
      "rule": "totalMs < responseBudgetMs của mọi Scenario gọi tích hợp đó"
    },
    "R9": {
      "severity": "Chặn baseline",
      "rule": "Tích hợp ghi không idempotent: RetryPolicy.idempotentOnly=true hoặc có Header idempotency key"
    },
    "R10": {
      "severity": "Chặn baseline",
      "rule": "ErrorMapping phủ đủ transient, permanent, unknownOutcome"
    },
    "R11": {
      "severity": "Cảnh báo",
      "rule": "ConnectionPool.maxTotal <= PartnerLimit.maxConcurrentConnections"
    },
    "R12": {
      "severity": "Chặn baseline",
      "rule": "Tích hợp queue: Channel có deliverySemantics và dlqName; atLeastOnce => consumerIdempotent"
    },
    "R13": {
      "severity": "Cảnh báo",
      "rule": "Mọi Risk có mitigation hoặc mitigatedBy"
    },
    "R14": {
      "severity": "Cảnh báo",
      "rule": "Assumption/OpenQuestion có owner, dueDate; quá hạn chưa xác nhận thì cảnh báo"
    },
    "R15": {
      "severity": "Cảnh báo",
      "rule": "Mọi NFR có verifiedBy một TestCase"
    },
    "R16": {
      "severity": "Cảnh báo",
      "rule": "Integration có contractConfirmed=true hoặc assumes một Assumption còn hạn"
    },
    "R17": {
      "severity": "Chặn baseline",
      "rule": "Nút Baselined không được sửa; thay đổi phải tạo nút mới supersedes nút cũ"
    }
  }
}

